CREATE TABLE IF NOT EXISTS match_operator_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,match_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME NULL,UNIQUE KEY user_match_operator(user_id,match_id),INDEX(match_id,status),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(match_id) REFERENCES matches(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
